$testCount = 76; $script:passed = 0
function Assert-True { param([bool]$Condition,[string]$Message) if (-not $Condition) { throw "ASSERT TRUE: $Message" } }
function Assert-Equal { param($Actual,$Expected,[string]$Message) if ((@($Actual) -join '|') -cne (@($Expected) -join '|')) { throw "ASSERT EQUAL: $Message" } }
function Assert-Throws { param([scriptblock]$Action,[string]$Text,[string]$Message) try { & $Action; throw "ASSERT THROW: $Message" } catch { Assert-True $_.Exception.Message.Contains($Text) $Message } }
function Pass { param([string]$Name) $script:passed++; Write-Host "PASS $script:passed/$testCount`: $Name" }
function Assert-EnvironmentSnapshot { param([object[]]$Expected,[string]$Message)
 $actual=Get-CodexDispatchOrchestratorCredentialSnapshot
 foreach($record in $Expected){$current=@($actual|Where-Object {[string]$_.name -ceq [string]$record.name})[0];Assert-Equal $current.exists $record.exists "$Message exists $($record.name)";Assert-Equal $current.value $record.value "$Message value $($record.name)"}
}
function New-Case {
 param([string]$Root,[string]$Name)
 $dir=Join-Path $Root $Name; $workspace=Join-Path $dir 'workspace'; $state=Join-Path $dir 'state'
 [void](New-Item -ItemType Directory -Force -Path $workspace,$state)
 $config=Join-Path $dir 'config.local.json'
 $doc=[ordered]@{version=1;workspace=[ordered]@{root=$workspace;scanDepth=1;allowReparsePoints=$false};runtime=[ordered]@{stateDirectory=$state};controlPlane=[ordered]@{provider='github';repository='example/control';defaultBranch='main'};routing=[ordered]@{fast=[ordered]@{enabled=$true};slow=[ordered]@{enabled=$true}};codex=[ordered]@{command='codex';workerSandbox='workspace-write';routerSandbox='read-only';approvalPolicy='never'};privacy=[ordered]@{exposeLocalPathsInIssues=$false;exposeThreadIdsInIssues=$false;includeOriginalTaskInIssues=$false};safety=[ordered]@{restrictToWorkspaceRoot=$true;requireExplicitAuthorizationFor=@('push','deploy')}}
 [IO.File]::WriteAllText($config,(ConvertTo-Json $doc -Depth 8),[Text.UTF8Encoding]::new($false))
 [IO.File]::WriteAllText((Join-Path $dir 'project-index.json'),'{"version":1,"projects":[]}',[Text.UTF8Encoding]::new($false))
 [pscustomobject]@{Root=$dir;Config=$config;State=$state}
}
function New-ResumeState {
 param($Case,[string]$Phase='worker',[string]$Status='needs_input')
 $s=& $newStatePath -Task 'immutable task' -ConfigPath $Case.Config
 if ($Phase -ceq 'worker' -and $Status -ceq 'needs_input') {
  & $updateStatePath -DispatchId $s.dispatchId -ExpectedRevision $s.revision -Phase routing -Status running -ConfigPath $Case.Config | Out-Null
  $s=& $getStatePath -DispatchId $s.dispatchId -ConfigPath $Case.Config
  & $updateStatePath -DispatchId $s.dispatchId -ExpectedRevision $s.revision -Phase worker -Status running -ProjectRepository owner/project -ConfigPath $Case.Config | Out-Null
  $s=& $getStatePath -DispatchId $s.dispatchId -ConfigPath $Case.Config
  & $updateStatePath -DispatchId $s.dispatchId -ExpectedRevision $s.revision -Phase worker -Status needs_input -ProjectRepository owner/project -ThreadId '11111111-1111-1111-1111-111111111111' -Report old -Question oldq -Context oldc -Options @('A','B') -ConfigPath $Case.Config | Out-Null
 } else { & $updateStatePath -DispatchId $s.dispatchId -ExpectedRevision $s.revision -Phase $Phase -Status $Status -Report route -Question q -Context c -Options @('A','B') -ConfigPath $Case.Config | Out-Null }
 return (& $getStatePath -DispatchId $s.dispatchId -ConfigPath $Case.Config)
}
function New-WorkerResult { param([string]$Status='completed',[string]$ThreadId='11111111-1111-1111-1111-111111111111',[string]$Diagnostic='failure')
 $options=[string[]]@(); if($Status -eq 'needs_input'){$options=[string[]]@('A','B')}
 [pscustomobject][ordered]@{version=1;status=$Status;project=[pscustomobject]@{name='untrusted';localPath='C:\bad';githubRepository='evil/project'};threadId=$ThreadId;report=if($Status -eq 'completed'){'done'}elseif($Status -eq 'needs_input'){'again'}else{''};question=if($Status -eq 'needs_input'){'choose?'}else{''};context=if($Status -eq 'needs_input'){'context'}else{''};options=$options;exitCode=if($Status -eq 'failed'){1}else{0};diagnostic=if($Status -eq 'failed'){$Diagnostic}else{''}}
}
