function Invoke-Resume { param($Case,$Fixture,$State,[string]$Answer=' answer ' ,[Int64]$Issue=42) $Fixture.Context | Add-Member -NotePropertyName DispatchId -NotePropertyValue $State.dispatchId -Force;Push-Location $Case.Root;try{Invoke-CodexDispatchResumeOrchestratorInternal -DispatchId $State.dispatchId -Answer $Answer -IssueNumber $Issue -ConfigPath $Case.Config -Dependencies $Fixture.Dependencies}finally{Pop-Location} }
function Read-State { param($Case,[string]$Id) & $getStatePath -DispatchId $Id -ConfigPath $Case.Config }
function Assert-PublicOutput { param($Value,[string]$Publication)
 Assert-Equal ($Value.PSObject.Properties.Name) @('version','dispatchId','revision','phase','status','projectRepository','report','question','context','options','diagnostic','issuePublication','issueNumber','issueUrl','projectionDiagnostic') 'public output order'
 foreach($forbidden in @('Task','Answer','ThreadId','localPath','project','token','credential')) { Assert-True ($Value.PSObject.Properties.Name -notcontains $forbidden) "public output excludes $forbidden" }
 Assert-Equal $Value.issuePublication $Publication 'issue publication enum'
}

